{"assembly_decision": {"action": "integrate", "base_id": "baseline-e1", "idea_ids": ["6a6df1ce02ae4c4e"], "rationale": "Use baseline-e1, the only correct measured source. Adapt T2’s unmeasured arithmetic hypothesis: cancel the target-mass factor and replace sqrt/division with rsqrtf-based inverse-distance cubing. The T2 trial was an infrastructure error, not performance or correctness evidence. This candidate is unvalidated; compile, check and measure it independently.
src/nbody_kernel.cu:
struct Particle { float x, y, z, vx, vy, vz, mass; };

extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;
    const Particle a = in[i];
    float fx = 0.0f, fy = 0.0f, fz = 0.0f;
    for (int j = 0; j < n; ++j) {
        if (i == j) continue;
        const float dx = in[j].x - a.x;
        const float dy = in[j].y - a.y;
        const float dz = in[j].z - a.z;
        const float distSq = dx*dx + dy*dy + dz*dz + 0.001f;
        const float invDist = rsqrtf(distSq);
        const float scale = in[j].mass * (invDist * invDist * invDist);
        fx += scale * dx;
        fy += scale * dy;
        fz += scale * dz;
    }
    Particle p = a;
    p.vx += fx * dt; p.vy += fy * dt; p.vz += fz * dt;
    p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
    out[i] = p;
}
