ults-780678/cuda-nbody/logs/e1/2d9d46a27e344d6a/search/attempt-001/sample-1.log", "/gpfs/scratch/nimarano/forest-engine-history-780448-a0639ccf408b4f3e918f7bcd63779d04/results-780678/cuda-nbody/logs/e1/2d9d46a27e344d6a/search/attempt-001/sample-2.log"], "mean_seconds": 0.001288624139156162, "reason": "", "score": 0.5897750119375894, "status": "valid", "times": [0.0012895126691762197, 0.0012918396004915902, 0.0012845201478006761], "tree_hash": "94aa3cc6ac746bbd3aa3fc0bfe6070fc03770949"}, "search_stop_reason": "infrastructure_error", "selections": [{"decision": {"action": "read", "base_id": "", "idea_ids": [], "rationale": "All four topic trials ended with infrastructure errors and produced no source, correctness, or timing evidence; do not interpret them as failed optimizations. baseline-e1 is the only valid measured program. Read its exact kernel source before attempting a narrowly scoped integration using the arithmetic hypothesis from T2.", "read": {"ids": ["baseline-e1"], "offset": 0, "operation": "source", "path": "src/nbody_kernel.cu", "query": ""}, "source_ids": []}, "id": "memory-select-e1-r1-t1", "read_result": {"commit": "9474e9b1105b774bc2858607f13fbdef946812ea", "file_sha256": "ab22e9f1e077f75420e407b68a4285d97a5912340297d1a700f98f40697b00bc", "id": "baseline-e1", "next_offset": null, "offset_unit": "characters", "path": "src/nbody_kernel.cu", "schema": "hpc-forest-memory-v1", "snapshot_digest": "238101b9728a332f5db5303a0cccf6935dc1f7490b478a27686868478cc8a9d0", "text": "// Structure "Array of Structures" (AoS) : intuitive mais naïve sur GPU
// car elle empêche la coalescence parfaite des accès mémoire.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Kernel CUDA naïf : Simulation gravitationnelle N-Corps (N-Body)
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;

    const float G = 1.0f;
    const float softening = 0.001f;

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    // Approche naïve : chaque thread parcourt toutes les particules en mémoire globale
    // sans utiliser de mémoire partagée (__shared__) ni mettre in[i] en registre.
    for (int j = 0; j < n; j++) {
        if (i == j) continue; // Divergence de branche inutile dans la boucle

        float dx = in[j].x - in[i].x;
        float dy = in[j].y - in[i].y;
        float dz = in[j].z - in[i].z;

        float distSq = dx * dx + dy * dy + dz * dz + softening;
        float dist = sqrtf(distSq); // Calcul coûteux (au lieu de rsqrtf)

        float f = (G * in[i].mass * in[j].mass) / (distSq * dist);

        fx += f * dx;
        fy += f * dy;
        fz += f * dz;
    }

    // Intégration d'Euler explicite
    Particle p = in[i];
    p.vx += (fx / p.mass) * dt;
    p.vy += (fy / p.mass) * dt;
    p.vz += (fz / p.mass) * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}

